package com.example.ancapp

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.BackHandler
import androidx.activity.compose.setContent
import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.Row
import androidx.compose.foundation.layout.PaddingValues
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.fillMaxWidth
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.foundation.rememberScrollState
import androidx.compose.foundation.text.KeyboardOptions
import androidx.compose.foundation.verticalScroll
import androidx.compose.material3.Button
import androidx.compose.material3.Card
import androidx.compose.material3.Checkbox
import androidx.compose.material3.CircularProgressIndicator
import androidx.compose.material3.ExtendedFloatingActionButton
import androidx.compose.material3.ListItem
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.OutlinedTextField
import androidx.compose.material3.Scaffold
import androidx.compose.material3.Text
import androidx.compose.material3.TextButton
import androidx.compose.material3.TopAppBar
import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateMapOf
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import androidx.compose.runtime.rememberCoroutineScope
import androidx.compose.runtime.setValue
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.text.input.KeyboardType
import androidx.compose.ui.unit.dp
import java.time.LocalDate
import java.time.Period
import java.time.temporal.ChronoUnit
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext

class MainActivity : ComponentActivity() {
  override fun onCreate(savedInstanceState: Bundle?) {
    super.onCreate(savedInstanceState)
    setContent { MaterialTheme { App() } }
  }
}

@Composable
fun App() {
  var patient by remember { mutableStateOf<Patient?>(null) }
  var formOpen by remember { mutableStateOf(false) }
  BackHandler(enabled = patient != null) {
    if (formOpen) formOpen = false else patient = null
  }
  val p = patient
  when {
    p == null -> RegisterScreen(onOpen = { patient = it })
    formOpen -> VisitFormScreen(p, onDone = { formOpen = false })
    else -> DetailScreen(p, onBack = { patient = null }, onNewVisit = { formOpen = true })
  }
}

@Composable
fun RegisterScreen(onOpen: (Patient) -> Unit) {
  var result by remember { mutableStateOf<Result<List<Patient>>?>(null) }
  LaunchedEffect(Unit) { result = runCatching { withContext(Dispatchers.IO) { loadRegister() } } }
  val today = LocalDate.now()
  Scaffold(topBar = { TopAppBar(title = { Text("Pregnant patients") }) }) { pad ->
    val modifier = Modifier.padding(pad).fillMaxSize()
    when (val r = result) {
      null -> Box(modifier, contentAlignment = Alignment.Center) { CircularProgressIndicator() }
      else -> r.fold(
        onSuccess = { patients ->
          LazyColumn(modifier) {
            items(patients) { p -> PatientRow(p, today, onClick = { onOpen(p) }) }
          }
        },
        onFailure = { Text("Could not load patients: ${it.message}", color = MaterialTheme.colorScheme.error, modifier = modifier.padding(16.dp)) },
      )
    }
  }
}

@Composable
fun DetailScreen(p: Patient, onBack: () -> Unit, onNewVisit: () -> Unit) {
  var result by remember { mutableStateOf<Result<List<Visit>>?>(null) }
  LaunchedEffect(p.id) { result = runCatching { withContext(Dispatchers.IO) { loadVisits(p.id) } } }
  val today = LocalDate.now()
  Scaffold(
    topBar = {
      TopAppBar(
        title = { Text(p.name) },
        navigationIcon = { TextButton(onClick = onBack) { Text("Back") } },
      )
    },
    floatingActionButton = {
      ExtendedFloatingActionButton(onClick = onNewVisit, text = { Text("New ANC visit") })
    },
  ) { pad ->
    LazyColumn(
      Modifier.padding(pad).fillMaxSize(),
      contentPadding = PaddingValues(16.dp),
      verticalArrangement = Arrangement.spacedBy(8.dp),
    ) {
      item { Text("Age ${Period.between(p.birthDate, today).years} · Due ${p.dueDate} · ${gestation(p.dueDate, today)}") }
      item { Text("ANC visits", style = MaterialTheme.typography.titleMedium) }
      when (val r = result) {
        null -> item { CircularProgressIndicator() }
        else -> r.fold(
          onSuccess = { visits ->
            if (visits.isEmpty()) item { Text("No visits recorded yet.") }
            items(visits) { v -> VisitCard(v) }
          },
          onFailure = { item { Text("Could not load visits: ${it.message}", color = MaterialTheme.colorScheme.error) } },
        )
      }
    }
  }
}

@Composable
fun VisitFormScreen(p: Patient, onDone: () -> Unit) {
  var questionnaire by remember { mutableStateOf<Result<List<QItem>>?>(null) }
  LaunchedEffect(Unit) { questionnaire = runCatching { withContext(Dispatchers.IO) { loadQuestionnaire() } } }
  val values = remember { mutableStateMapOf("visit-date" to LocalDate.now().toString()) }
  var errors by remember { mutableStateOf(emptyList<String>()) }
  var saving by remember { mutableStateOf(false) }
  var saveError by remember { mutableStateOf<String?>(null) }
  val scope = rememberCoroutineScope()
  Scaffold(
    topBar = {
      TopAppBar(
        title = { Text("ANC visit · ${p.name}") },
        navigationIcon = { TextButton(onClick = onDone) { Text("Cancel") } },
      )
    },
  ) { pad ->
    val modifier = Modifier.padding(pad).fillMaxSize()
    when (val r = questionnaire) {
      null -> Box(modifier, contentAlignment = Alignment.Center) { CircularProgressIndicator() }
      else -> r.fold(
        onSuccess = { items ->
          Column(
            modifier.padding(16.dp).verticalScroll(rememberScrollState()),
            verticalArrangement = Arrangement.spacedBy(12.dp),
          ) {
            FormItems(items, values)
            errors.forEach { Text(it, color = MaterialTheme.colorScheme.error) }
            saveError?.let { Text(it, color = MaterialTheme.colorScheme.error) }
            Button(
              enabled = !saving,
              onClick = {
                errors = problems(items, values)
                if (errors.isEmpty()) {
                  saving = true
                  saveError = null
                  val snapshot = values.toMap()
                  scope.launch {
                    runCatching { withContext(Dispatchers.IO) { saveVisit(p.id, items, snapshot) } }
                      .onSuccess { onDone() }
                      .onFailure { saving = false; saveError = "Save failed: ${it.message}" }
                  }
                }
              },
            ) { Text("Save visit") }
          }
        },
